          + (t.underCount ? t.underCount + ' of ' + a.hires.length + ' hires underperformed' : 'No hire underperformed') + (t.mixedCount ? ', ' + t.mixedCount + ' had a mixed result.' : '.');
      const worst = t.worst ? I.byId[t.worst] : null;
