        const reasons = h.reasons.slice(0, 3).map(r => ({ icon: r.icon, cls: r.cls, text: r.text }));
        const plus = h.positives.slice(0, h.verdict === 'good' ? 3 : 1).map(p => ({ icon: p.icon, cls: 'ok', text: p.text }));
        const lines = h.verdict === 'good' ? plus.concat(reasons.filter(r => r.cls !== 'mu').slice(0, 1)) : reasons.concat(plus);
        if (!lines.length) lines.push({ icon: 'check', cls: 'ok', text: 'Did the job: no points lost to the twist, friction or price.' });
