    if (h.verdict === 'under') return { m: 'sad', l: 'Off day', q: 'Not my best quarter. I know I can do better.' };
    if (h.verdict === 'mixed') return { m: 'neutral', l: 'Mixed result', q: 'Some of it worked, some of it didn’t.' };
    if (rescued) return { m: 'joy', l: 'Relieved', q: 'Thank you for covering me out there!' };
