    if (code.length !== NET.CONFIG.codeLen) { u.olErr = 'Enter the ' + NET.CONFIG.codeLen + '-character lobby code.'; this.redraw(); return; }
    if (!name) { u.olErr = 'Enter your name so the host knows who joined.'; this.redraw(); return; }
