      sub: isAll ? 'Average of each player’s best scores · players with 3 or more problems' : co.name + ' · budget ' + this.money(r.budget) + ' · best score per player',
      loading: loading, err: err, errText: cur.err || '', has: has, rows: rows,
      empty: !!c && !loading && !err && !rows.length,
