    const HL = { neutral: 'Steady', focused: 'Focused', confident: 'Confident', nervous: 'Sweating', panic: 'Panicking', frustrated: 'Frustrated', joy: 'Pumped', sad: 'Gutted', chill: 'Relaxed' };
