    if (st.h !== this._lh) { this._lh = st.h; this._lhN = (this._lhN || 0) + 1; }
    if (st.a !== this._la) { this._la = st.a; this._laN = (this._laN || 0) + 1; }
    if (st.t !== this._lt) { this._lt = st.t; this._ltN = (this._ltN || 0) + 1; }
    const MOODS = ['excited', 'joy', 'neutral', 'nervous', 'excited', 'neutral'];
