    const c = I.byId[u.profile], fm = this.fnMeta(c.function), pm = this.probMeta(u.problem), rd = this.round();
    const pool = this.poolIds().map(id => I.byId[id]);
    const avg = f => pool.reduce((s, x) => s + f(x), 0) / pool.length;
    const first = c.name.split(' ')[0];
    // fit for the chosen problem: every competency the round weights, by weight
    const keys = Object.keys(rd.weights).filter(k => rd.weights[k] > 0).sort((a, b) => rd.weights[b] - rd.weights[a]);
    const fit = keys.map(k => {
      const rank = 1 + pool.filter(x => x.comp[k] > c.comp[k]).length;
      return { name: this.compShort(k), w: Math.round(rd.weights[k] * 100) + '%', v: this.f1(c.comp[k]), pct: c.comp[k] * 10, avg: Math.round(avg(x => x.comp[k]) * 100) / 10,
        rank: '#' + rank + ' of ' + pool.length, rkCls: rank <= 5 ? 'gold' : rank > pool.length - 5 ? 'mu' : '' };
    });
