    const spokes = codes.map((_, i) => { const p = pt(i, 10); return { x: Math.round(p[0] * 10) / 10, y: Math.round(p[1] * 10) / 10 }; });
    const axes = codes.map((k, i) => { const p = pt(i, 11.9); return { label: this.compShort(k), v: this.f1(c.comp[k]), l: Math.round(p[0] / 260 * 1000) / 10, t: Math.round(p[1] / 260 * 1000) / 10 }; });
    // attributes vs pool average
