      open: true, anim: '', id: c.id, name: c.name, first: first, ini: this.ini(c.name), photo: this.photo(c.id, this.empState(c.id).m),
      moodLabel: this.empState(c.id).l, quote: this.empState(c.id).q, moodCls: 'em-' + this.empState(c.id).m,
      reacts: [['nervous', 'On the block'], ['excited', 'Bidding war'], ['joy', 'Hired'], ['sad', 'Passed over'], ['stressed', 'Hit by a twist'], ['neutral', 'Steady']].map(x => ({ photo: this.photo(c.id, x[0]), label: x[1], cls: 'em-' + x[0] })), color: fm.c, icon: fm.i, fn: fm.s, ring: c.isStar ? 'star-ring' : '', tier: c.tier,
