      start: this.money(c.startingBid), bench: this.money(c.benchmark), ratio: Math.round(c.startingBid / c.benchmark * 100) + '%',
      priceRank: pr + ' of ' + peersAll.length, priceRankSub: 'cheapest opening bid in ' + fm.s,
      problem: this.shortProblem(), pColor: pm.c,
      scopeCls: inScope ? 'in' : 'out', scopeIcon: inScope ? 'check' : 'warn', scopeColor: inScope ? '#33E0A1' : '#FFB547',
      scopeTitle: inScope ? fm.s + ' is a core function for ' + this.shortProblem() : fm.s + ' is a support function for ' + this.shortProblem(),
